import React, { FunctionComponent } from 'react';
import classNames from 'classnames';
import { Field } from 'react-final-form';
import { defineMessages } from 'react-intl';
import { useTranslation } from '@getvim/translate';
import { InputValidationMessage, PhoneNumberInput } from '../../../atoms';
import { PhoneNumberType } from '../../../types';
import es from './translations/es.json';

const VALID_PHONE_NUMBER_LENGTH = 10;
const VALID_DIGITAL_CODE_LENGTH = 2;
const INVALID_FIRST_DIGITS = ['0', '1'];

const messages = defineMessages({
  invalid: {
    defaultMessage: ' is invalid',
    id: 'schemaValidator.invalid',
  },
  required: {
    defaultMessage: ' is required',
    id: 'schemaValidator.required',
  },
});

export type PhoneInputProps = {
  id?: string;
  label: string;
  name: string;
  className?: string;
  required?: boolean;
};

const validatePhoneNumber = (
  value: PhoneNumberType,
  isRequired: boolean,
  intl: { formatMessage: (arg0: { defaultMessage: string; id: string }) => any },
): string | undefined => {
  if (isRequired && !value?.number) {
    return intl.formatMessage(messages.required);
  }

  return !value?.number ||
    (value?.number.length === VALID_PHONE_NUMBER_LENGTH &&
      value?.countryDialingCode.length === VALID_DIGITAL_CODE_LENGTH &&
      !INVALID_FIRST_DIGITS.includes(value?.number[0]))
    ? undefined
    : intl.formatMessage(messages.invalid);
};

const FormPhoneInput: FunctionComponent<PhoneInputProps> = ({
  id,
  label,
  name,
  className,
  required = false,
}) => {
  const intl = useTranslation({ es } as any);
  return (
    <Field
      name={name}
      validate={(value) => validatePhoneNumber(value, required, intl)}
      render={({ input, meta }) => (
        <>
          <PhoneNumberInput
            className={classNames(className, meta.error && meta.touched && 'has-error')}
            type="text"
            active={meta.active || input.value.number}
            label={label}
            id={id}
            {...input}
          />
          {meta.error && meta.touched && (
            <InputValidationMessage>{label + meta.error}</InputValidationMessage>
          )}
        </>
      )}
    />
  );
};

export default FormPhoneInput;
